import * as React from "react";
import { CommonProps } from "../../utility/commonProps";
export interface DataTableProps extends React.ComponentPropsWithoutRef<"table">, CommonProps {
    /**
     * The content for the data table.
     */
    children: React.ReactNode;
}
/**
 * Data Table displays a set of related information in rows and columns.
 *
 * - {@link https://livingdesign.walmart.com/components/data-table/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/data-table/react/ React documentation}
 *
 * ### Content
 *
 * The Data Table accepts content through the `children` prop.
 *
 * ```tsx
 * <DataTable>
 *   <DataTableHead>
 *     <DataTableRow>
 *       <DataTableHeader>First Name</DataTableHead>
 *       <DataTableHeader>Last Name</DataTableHead>
 *     </DataTableRow>
 *   <DataTableHead>
 *   <DataTableBody>
 *     <DataTableRow>
 *       <DataTableCell>James</DataTableCell>
 *       <DataTableCell>Kirk</DataTableCell>
 *     </DataTableRow>
 *   </DataTableBody>
 * </DataTable>
 * ```
 */
export declare const DataTable: React.FunctionComponent<DataTableProps>;
